import{_ as t,o,c as d,ag as a}from"./chunks/framework.HG0H2VLS.js";const p=JSON.parse('{"title":"FullBadge — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/components/FullBadge/FullBadge.figma-notes.md","filePath":"public/demos/src/components/FullBadge/FullBadge.figma-notes.md"}'),i={name:"public/demos/src/components/FullBadge/FullBadge.figma-notes.md"};function n(r,e,s,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="fullbadge-—-figma-notes" tabindex="-1">FullBadge — Figma Notes <a class="header-anchor" href="#fullbadge-—-figma-notes" aria-label="Permalink to &quot;FullBadge — Figma Notes&quot;">​</a></h1><p><strong>Tier:</strong> Component <strong>Built:</strong> 2026-08-25 (extracted during Seating Planner wave 3) <strong>Files:</strong> <code>FullBadge.css</code>, <code>FullBadge.html</code>, <code>FullBadge.figma-notes.md</code><strong>Consumed by:</strong> RoomCard, TableCard <strong>JS:</strong> none</p><h2 id="there-is-no-figma-component-for-this" tabindex="-1">There is no Figma component for this <a class="header-anchor" href="#there-is-no-figma-component-for-this" aria-label="Permalink to &quot;There is no Figma component for this&quot;">​</a></h2><p>That is the whole reason this file needs reading. FullBadge was <strong>extracted from code</strong>, not built from a component set. Figma draws it as an inline <code>Full-Badge</code> frame in two separate places:</p><table tabindex="0"><thead><tr><th>Consumer</th><th>Figma node</th><th>Notes</th></tr></thead><tbody><tr><td>RoomCard</td><td><code>3470:84969</code></td><td>Full / Default, desktop</td></tr><tr><td>RoomCard</td><td><code>3474:90697</code></td><td>Full / Selected, desktop</td></tr><tr><td>TableCard</td><td><code>3472:85703</code></td><td>Full / Default, desktop</td></tr><tr><td>TableCard</td><td><code>3484:186684</code></td><td>Full / Default, mobile — 46px wide, 1px off the others</td></tr></tbody></table><p><code>get_metadata</code> reports every one of them as <code>&lt;frame&gt;</code>, never <code>&lt;instance&gt;</code> — so they are four hand-drawn copies of the same thing, not a component with four usages. They are identical apart from that 1px.</p><p><strong>Consequences, in order of how likely they are to bite:</strong></p><ol><li><strong>No Code Connect.</strong> <code>figma.connect</code> needs a component to attach to. Until Figma makes one, a designer clicking the badge sees nothing. There is deliberately no <code>FullBadge.figma.ts</code> — an empty or frame-targeted one would be worse than none.</li><li><strong>Figma can drift from itself.</strong> Four copies means four things to keep in step; the mobile one is already 1px out.</li><li><strong>The variant matrix is empty.</strong> No Type, State, Size or Device axes exist, so there are no modifiers here and none should be added without a Figma counterpart.</li></ol><blockquote><p><strong>Ask the designer to promote it to a real component</strong>, then add the <code>.figma.ts</code> and replace the four frames with instances. This note can go when that happens.</p></blockquote><h2 id="why-it-was-extracted" tabindex="-1">Why it was extracted <a class="header-anchor" href="#why-it-was-extracted" aria-label="Permalink to &quot;Why it was extracted&quot;">​</a></h2><p>It was originally scoped inside RoomCard as <code>.room-card__badge</code> (2026-08-25). When TableCard turned out to draw an identical copy, the designer chose extraction over duplicating it — so the open contrast question below and the check-icon sizing live in one file rather than two.</p><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-surface-success</code></td><td><code>background-color</code></td><td></td></tr><tr><td><code>--ai-text-invert</code></td><td><code>color</code></td><td>was the <code>Grey/0</code> primitive in Figma</td></tr><tr><td><code>--ai-radius-full</code></td><td><code>border-radius</code></td><td></td></tr><tr><td><code>--ai-spacing-2</code></td><td><code>padding-inline</code> (6px)</td><td></td></tr><tr><td><code>--ai-spacing-0-5</code></td><td><code>padding-block</code> (2px)</td><td></td></tr><tr><td><code>--ai-spacing-1</code></td><td><code>gap</code> (4px)</td><td>Figma bound <code>border/width/border-3</code> — see below</td></tr><tr><td><code>--ai-font-title</code></td><td><code>font-family</code></td><td></td></tr><tr><td><code>--ai-font-fixed-6xs</code></td><td><code>font-size</code> (9px)</td><td>the token added 2026-08-25</td></tr><tr><td><code>--ai-font-bold</code></td><td><code>font-weight</code></td><td></td></tr><tr><td><code>--ai-tracking-7</code></td><td><code>letter-spacing</code></td><td>CSS leads Figma — see below</td></tr></tbody></table><h2 id="token-gaps-and-decisions" tabindex="-1">Token gaps and decisions <a class="header-anchor" href="#token-gaps-and-decisions" aria-label="Permalink to &quot;Token gaps and decisions&quot;">​</a></h2><p>Resolved with the designer 2026-08-25 rather than invented.</p><table tabindex="0"><thead><tr><th>Figma</th><th>Decision</th></tr></thead><tbody><tr><td><code>gap</code> bound to <code>border/width/border-3</code> (3px)</td><td><strong><code>--ai-spacing-1</code></strong> (4px). A border-width token driving a flex gap, and 3px matches no spacing step. Figma updated.</td></tr><tr><td>label <code>9px</code>, unbound</td><td><strong>New token <code>--ai-font-fixed-6xs</code></strong>, created in Figma and re-exported the same day.</td></tr><tr><td><code>Grey/0</code> primitive (<code>#ffffff</code>)</td><td><strong><code>--ai-text-invert</code></strong>, which is exactly <code>#ffffff</code>.</td></tr><tr><td>check icon <code>7×7</code></td><td><strong>Raw 10×10</strong> — see below. No icon token fits: the smallest, <code>--ai-icon-size-xs</code>, is 12px and will not sit in a 15px badge.</td></tr></tbody></table><h2 id="two-places-the-css-leads-figma" tabindex="-1">Two places the CSS leads Figma <a class="header-anchor" href="#two-places-the-css-leads-figma" aria-label="Permalink to &quot;Two places the CSS leads Figma&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td>check icon</td><td><code>7×7</code>, default stroke</td><td><strong><code>10×10</code>, <code>stroke-width: 4</code></strong></td></tr><tr><td>label <code>letter-spacing</code></td><td><strong>not set</strong></td><td><strong><code>--ai-tracking-7</code></strong> (0.05em)</td></tr></tbody></table><p><strong>The check had to grow to stay legible.</strong> Lucide renders on a 24-unit viewBox, so its default <code>stroke-width: 2</code> thins to roughly 0.6px once scaled to 7px — a hairline that all but disappeared against the green. 10px with <code>stroke-width: 4</code> reads properly. Verified against a true 1× raster upscaled with nearest-neighbour, not a scaled vector preview, because scaling hides exactly that thinning. CSS <code>stroke-width</code> beats the <code>stroke-width=&quot;2&quot;</code> presentation attribute Lucide writes onto the <code>&lt;svg&gt;</code>; both <code>[data-lucide]</code> and <code>svg</code> are targeted because <code>createIcons()</code> swaps the element.</p><p><strong>The tracking is an addition</strong> — 9px bold uppercase sets very tight, and it matches the treatment TableType&#39;s uppercase micro-label was given.</p><p>Together these render the badge at <strong>49.9×15 against Figma&#39;s 45×15</strong>. If Figma is brought into line, the frame wants to be about 50px.</p><h2 id="accessibility-—-one-open-item" tabindex="-1">Accessibility — one open item <a class="header-anchor" href="#accessibility-—-one-open-item" aria-label="Permalink to &quot;Accessibility — one open item&quot;">​</a></h2><p><strong>White on <code>--ai-surface-success</code> measures 3.16:1</strong>, under the 4.5:1 WCAG AA requires for 9px bold text. It needs either a darker success or a dark label — a palette decision, not something this component can fix. <strong>Deliberately left open</strong> at the designer&#39;s direction 2026-08-25; tracked with the other unresolved pairs in <code>docs/contrast-audit.md</code>.</p><p>Fixing it here now fixes it for both consumers at once, which is part of why extraction was worth doing.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Ships as a <code>&lt;span&gt;</code>.</strong> It was a <code>&lt;p&gt;</code> while scoped inside RoomCard, which needed a <code>margin: 0</code> reset — the reset is kept defensively, since a caller reaching for a block element would otherwise inherit margins and push its row out of alignment. That bug did occur once, adding 16px to RoomCard&#39;s Full card only.</li><li><strong><code>flex-shrink: 0</code></strong> because it always shares a flex row with a growing text node.</li><li>The Lucide name is <code>check</code>, matching Figma&#39;s <code>CheckIcon</code> / <code>check</code> layer names.</li></ul>',26)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
